using ClinicManager.BUS;using ClinicManager.DTO;using System.ComponentModel;using System.Data;
namespace ClinicManager.GUI;
public sealed class MainForm:Form
{
 readonly ClinicService service=new();readonly TabControl tabs=new(){Dock=DockStyle.Fill};readonly DataGridView medicineGrid=Grid(),visitGrid=Grid(),lineGrid=Grid(),invoiceGrid=Grid();
 readonly TextBox phone=new(){Width=145},patientName=new(){Width=210},symptoms=new(){Width=230},diagnosis=new(){Width=210},medicineName=new(){Width=190},unit=new(){Width=80},usage=new(){Width=210};
 readonly NumericUpDown birthYear=new(){Width=90,Minimum=1900,Maximum=DateTime.Now.Year,Value=1990},qty=new(){Width=65,Minimum=1,Maximum=1000,Value=1},medicineStock=new(){Width=80,Minimum=0,Maximum=100000},fee=new(){Width=100,Minimum=0,Maximum=10000000,DecimalPlaces=0},medicinePrice=new(){Width=100,Minimum=0,Maximum=10000000,DecimalPlaces=0};
 readonly ComboBox medicineChoice=new(){Width=240,DropDownStyle=ComboBoxStyle.DropDownList};readonly BindingList<PrescriptionLineDto> lines=new();
 int? patientId,visitId,medicineId,orderId;
 public MainForm(){Text="CarePoint | Tiếp nhận & kê đơn phòng khám";Width=1380;Height=880;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(246,248,251);BuildIntake();BuildMedicines();BuildVisits();Controls.Add(tabs);Shown+=(_,_)=>RefreshAll();}
 static DataGridView Grid()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,BackgroundColor=Color.White,BorderStyle=BorderStyle.None};static Label L(string s)=>new(){Text=s,AutoSize=true,Margin=new Padding(6,9,2,2)};static Button B(string s,EventHandler e)=>new Button{Text=s,AutoSize=true,Height=34,Margin=new Padding(3),BackColor=Color.White,FlatStyle=FlatStyle.Flat}.Also(x=>x.Click+=e);static FlowLayoutPanel Bar(int h)=>new(){Dock=DockStyle.Top,Height=h,Padding=new Padding(6),WrapContents=true};TabPage Page(string s){var p=new TabPage(s){Padding=new Padding(12),BackColor=BackColor};tabs.TabPages.Add(p);return p;}
 void BuildIntake(){var p=Page("Tiếp nhận / kê đơn");var head=Bar(112);head.Controls.AddRange(new Control[]{L("Số điện thoại"),phone,B("Tra cứu",(_,_)=>Search()),L("Họ tên"),patientName,L("Năm sinh"),birthYear,L("Triệu chứng"),symptoms,B("Tiếp nhận mới",(_,_)=>Register()),B("Tạo hồ sơ khám",(_,_)=>CreateVisit()),L("Chẩn đoán"),diagnosis});var order=Bar(104);order.Controls.AddRange(new Control[]{L("Thuốc"),medicineChoice,L("SL"),qty,L("Liều dùng"),usage,B("Thêm thuốc vào đơn",(_,_)=>AddLine()),L("Tiền khám"),fee,B("Lưu & xuất đơn",(_,_)=>SaveOrder()),B("Thanh toán đơn",(_,_)=>PayOrder())});lineGrid.DataSource=lines;var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=230};split.Panel1.Controls.Add(lineGrid);split.Panel2.Controls.Add(invoiceGrid);invoiceGrid.DataSource=null;var label=new Label{Text="Đơn thuốc đang kê",Dock=DockStyle.Top,Height=28,Font=new Font("Segoe UI",11,FontStyle.Bold)};split.Panel1.Controls.Add(label);split.Panel1.Controls.SetChildIndex(label,0);p.Controls.Add(split);p.Controls.Add(order);p.Controls.Add(head);}
 void BuildMedicines(){var p=Page("Thuốc / tồn kho");var top=Bar(96);top.Controls.AddRange(new Control[]{L("Tên thuốc"),medicineName,L("ĐVT"),unit,L("Đơn giá"),medicinePrice,L("Tồn kho"),medicineStock,B("Thêm thuốc",(_,_)=>SaveMedicine(null)),B("Cập nhật",(_,_)=>SaveMedicine(medicineId)),B("Nhập tồn",(_,_)=>ImportStock()),B("Làm mới",(_,_)=>LoadMedicines())});p.Controls.Add(medicineGrid);p.Controls.Add(top);medicineGrid.SelectionChanged+=(_,_)=>SelectMedicine();}
 void BuildVisits(){var p=Page("Hồ sơ khám");var top=Bar(48);top.Controls.Add(B("Tải hồ sơ gần đây",(_,_)=>LoadVisits()));p.Controls.Add(visitGrid);p.Controls.Add(top);}
 void RefreshAll(){try{LoadMedicines();LoadVisits();}catch(Exception ex){Error(ex);}}
 void LoadMedicines(){medicineGrid.DataSource=service.Data.Medicines();var t=service.Data.Medicines();medicineChoice.DataSource=t;medicineChoice.DisplayMember="TenThuoc";medicineChoice.ValueMember="MaThuoc";medicineChoice.SelectedIndex=t.Rows.Count>0?0:-1;}
 void LoadVisits(){visitGrid.DataSource=service.Data.Visits();}
 void Search(){try{if(string.IsNullOrWhiteSpace(phone.Text))throw new InvalidOperationException("Nhập số điện thoại cần tra cứu.");var t=service.Data.FindPatient(phone.Text.Trim());if(t.Rows.Count==0){patientId=null;visitId=null;MessageBox.Show("Chưa có bệnh nhân theo số điện thoại này. Nhập họ tên, năm sinh và bấm Tiếp nhận mới.");return;}var r=t.Rows[0];patientId=Convert.ToInt32(r["MaBN"]);patientName.Text=r["HoTen"].ToString();if(r["NamSinh"]!=DBNull.Value)birthYear.Value=Convert.ToDecimal(r["NamSinh"]);MessageBox.Show($"Đã tìm thấy bệnh nhân #{patientId}: {patientName.Text}. Tạo hồ sơ khám để tiếp tục.");}catch(Exception ex){Error(ex);}}
 void Register(){try{service.ValidatePatient(patientName.Text,phone.Text.Trim());visitId=service.Data.RegisterPatient(patientName.Text.Trim(),phone.Text.Trim(),(int)birthYear.Value,symptoms.Text.Trim());patientId=null;var t=service.Data.FindPatient(phone.Text.Trim());if(t.Rows.Count>0)patientId=Convert.ToInt32(t.Rows[0]["MaBN"]);LoadVisits();MessageBox.Show($"Đã tiếp nhận bệnh nhân và tạo hồ sơ khám #{visitId}.");}catch(Exception ex){Error(ex);}}
 void CreateVisit(){try{if(patientId is null)throw new InvalidOperationException("Tra cứu bệnh nhân đã có trước, hoặc dùng Tiếp nhận mới.");visitId=service.Data.CreateVisit(patientId.Value,symptoms.Text.Trim());LoadVisits();MessageBox.Show($"Đã tạo hồ sơ khám #{visitId}.");}catch(Exception ex){Error(ex);}}
 void AddLine(){try{if(medicineChoice.SelectedItem is not DataRowView r)throw new InvalidOperationException("Chọn thuốc.");int id=Convert.ToInt32(r["MaThuoc"]);if(lines.Any(x=>x.MedicineId==id))throw new InvalidOperationException("Thuốc đã có trong đơn; hãy tạo đơn khác nếu cần.");lines.Add(new PrescriptionLineDto{MedicineId=id,Medicine=r["TenThuoc"].ToString()!,Quantity=(int)qty.Value,Usage=string.IsNullOrWhiteSpace(usage.Text)?"Theo hướng dẫn bác sĩ":usage.Text.Trim(),UnitPrice=Convert.ToDecimal(r["DonGia"])});}catch(Exception ex){Error(ex);}}
 void SaveOrder(){try{if(visitId is null)throw new InvalidOperationException("Hãy tiếp nhận bệnh nhân hoặc tạo hồ sơ khám trước.");service.ValidateOrder(visitId.Value,fee.Value,lines);orderId=service.Data.SavePrescription(visitId.Value,fee.Value,diagnosis.Text,lines.ToList());lines.Clear();LoadMedicines();invoiceGrid.DataSource=service.Data.Invoice(orderId.Value);MessageBox.Show($"Đã lưu đơn #{orderId}. Thuốc đã xuất kho trong giao dịch SQL. Đơn đang chờ thanh toán.");}catch(Exception ex){Error(ex);}}
 void PayOrder(){try{if(orderId is null)throw new InvalidOperationException("Lưu đơn thuốc trước khi thanh toán.");service.Data.Pay(orderId.Value);invoiceGrid.DataSource=service.Data.Invoice(orderId.Value);MessageBox.Show($"Đơn #{orderId} đã thanh toán. Tổng tiền: {invoiceGrid.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow).Select(r=>r.Cells["TongTien"].Value).FirstOrDefault()}");}catch(Exception ex){Error(ex);}}
 void SelectMedicine(){if(medicineGrid.CurrentRow?.DataBoundItem is not DataRowView r)return;medicineId=Convert.ToInt32(r["MaThuoc"]);medicineName.Text=r["TenThuoc"].ToString();unit.Text=r["DonViTinh"].ToString();medicinePrice.Value=Convert.ToDecimal(r["DonGia"]);medicineStock.Value=Convert.ToDecimal(r["SoLuongTon"]);}
 void SaveMedicine(int? id){try{service.ValidateMedicine(medicineName.Text,unit.Text,medicinePrice.Value,(int)medicineStock.Value);service.Data.SaveMedicine(id,medicineName.Text.Trim(),unit.Text.Trim(),medicinePrice.Value,(int)medicineStock.Value);LoadMedicines();}catch(Exception ex){Error(ex);}}
 void ImportStock(){if(medicineId is null){MessageBox.Show("Chọn thuốc trước.");return;}try{int old=service.Data.Medicines().Select($"MaThuoc={medicineId.Value}")[0].Field<int>("SoLuongTon");medicineStock.Value=Math.Min(medicineStock.Maximum,old+medicineStock.Value);service.Data.SaveMedicine(medicineId,medicineName.Text,unit.Text,medicinePrice.Value,(int)medicineStock.Value);LoadMedicines();}catch(Exception ex){Error(ex);}}
 void Error(Exception ex)=>MessageBox.Show(ex.Message,"Thông báo",MessageBoxButtons.OK,MessageBoxIcon.Warning);
}
internal static class ClinicControlExtensions{internal static T Also<T>(this T c,Action<T> action) where T:Control{action(c);return c;}}
